/* =========================================================
   Language switching (flag-based menu, no icon fonts)
========================================================= */
const flagByLang = { en: "https://flagcdn.com/w40/gb.png", fr: "https://flagcdn.com/w40/fr.png", ar: "https://flagcdn.com/w40/dz.png" };
const codeByLang  = { en: "EN", fr: "FR", ar: "AR" };

function applyLanguage(lang) {
  const dict = translations[lang] || translations.en;

  document.querySelectorAll("[data-i18n]").forEach(el => {
    const key = el.getAttribute("data-i18n");
    if (dict[key] !== undefined) el.textContent = dict[key];
  });

  document.title = dict["meta.title"];
  document.documentElement.lang = lang;
  document.documentElement.dir = lang === "ar" ? "rtl" : "ltr";

  const langFlag = document.getElementById("langFlag");
  const langCode = document.getElementById("langCode");
  if (langFlag) langFlag.src = flagByLang[lang];
  if (langCode) langCode.textContent = codeByLang[lang];

  document.querySelectorAll(".lang-menu li").forEach(li => {
    li.classList.toggle("active", li.dataset.lang === lang);
  });

  localStorage.setItem("site-lang", lang);

  // Notify AI chat (and any other listeners) of instant language change
  document.dispatchEvent(new CustomEvent("site-lang-changed", { detail: { lang } }));
}

function initLanguage() {
  const saved = localStorage.getItem("site-lang");
  const browserLang = (navigator.language || "en").slice(0, 2);
  const initial = saved || (translations[browserLang] ? browserLang : "en");
  applyLanguage(initial);
}

const langSwitcher = document.getElementById("langSwitcher");
const langBtn = document.getElementById("langBtn");
langBtn?.addEventListener("click", (e) => {
  e.stopPropagation();
  langSwitcher.classList.toggle("open");
});
document.querySelectorAll(".lang-menu li").forEach(li => {
  li.addEventListener("click", () => {
    applyLanguage(li.dataset.lang);
    langSwitcher.classList.remove("open");
  });
});
document.addEventListener("click", (e) => {
  if (langSwitcher && !langSwitcher.contains(e.target)) {
    langSwitcher.classList.remove("open");
  }
});

initLanguage();

/* =========================================================
   Light / dark theme toggle
========================================================= */
function applyTheme(theme) {
  document.documentElement.setAttribute("data-theme", theme);
  localStorage.setItem("site-theme", theme);
}

function initTheme() {
  const saved = localStorage.getItem("site-theme");
  const prefersLight = window.matchMedia && window.matchMedia("(prefers-color-scheme: light)").matches;
  const initial = saved || (prefersLight ? "light" : "dark");
  applyTheme(initial);
}

const themeToggle = document.getElementById("themeToggle");
themeToggle?.addEventListener("click", () => {
  const current = document.documentElement.getAttribute("data-theme") === "light" ? "light" : "dark";
  applyTheme(current === "light" ? "dark" : "light");
});

initTheme();

/* =========================================================
   Mobile nav toggle
========================================================= */
const navToggle = document.getElementById('navToggle');
const navLinks = document.getElementById('navLinks');
const navOverlay = document.getElementById('navOverlay');

function openMenu(){
  navLinks.classList.add('open');
  navToggle.classList.add('active');
  navOverlay.classList.add('show');
  navToggle.setAttribute('aria-expanded', 'true');
  document.body.classList.add('nav-open');
}
function closeMenu(){
  navLinks.classList.remove('open');
  navToggle.classList.remove('active');
  navOverlay.classList.remove('show');
  navToggle.setAttribute('aria-expanded', 'false');
  document.body.classList.remove('nav-open');
}

navToggle?.addEventListener('click', () => {
  navLinks.classList.contains('open') ? closeMenu() : openMenu();
});

// auto-close when clicking outside the menu
navOverlay?.addEventListener('click', closeMenu);

// auto-close on Escape
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && navLinks.classList.contains('open')) closeMenu();
});

// auto-close if the viewport grows back to desktop size
window.addEventListener('resize', () => {
  if (window.innerWidth > 980 && navLinks.classList.contains('open')) closeMenu();
});

navLinks?.querySelectorAll('a').forEach(link => {
  link.addEventListener('click', () => {
    closeMenu();
    navLinks.querySelectorAll('a').forEach(a => a.classList.remove('active'));
    link.classList.add('active');
  });
});

/* =========================================================
   Scroll reveal — adds life to sections as they enter view
========================================================= */
const revealTargets = document.querySelectorAll(
  '.service-card, .project-card, .stat, .about-photo, .hero-text, .hero-visual, .tech-chip'
);
revealTargets.forEach(el => el.classList.add('reveal'));

const revealObserver = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      entry.target.classList.add('in-view');
      revealObserver.unobserve(entry.target);
    }
  });
}, { threshold: 0.12, rootMargin: '0px 0px -40px 0px' });

revealTargets.forEach(el => revealObserver.observe(el));

